import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { ratesKey } from './useRates';

/**
 * Paste lines of grade,rate,from,to (the last two may be absent or blank): a rate per line, set in
 * order exactly as the rate form would set it. Every line is checked by the form's rules first: one
 * refused line refuses the whole import. Shows how many were set; the count goes while the next
 * press runs.
 */
function ImportRates({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const [text, setText] = useState('');
  const importing = useMutation({
    mutationFn: (t: string) =>
      postJson<{ set: number }>(`/api/sheets/${encodeURIComponent(sheet)}/import-rates`, { text: t, user }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ratesKey(sheet) }),
  });
  return (
    <section data-testid="import-rates-panel">
      <label>
        Import rates (grade,rate,from,to per line)
        <br />
        <textarea
          data-testid="import-rates"
          rows={4}
          cols={50}
          value={text}
          onChange={(e) => {
            setText(e.target.value);
            importing.reset();
          }}
        />
      </label>
      <br />
      <button
        type="button"
        data-testid="import-rates-submit"
        disabled={importing.isPending}
        onClick={() => {
          importing.reset();
          importing.mutate(text);
        }}
      >
        Import rates
      </button>
      {importing.isSuccess && (
        <span>
          {' '}
          Set <strong data-testid="import-rates-set">{importing.data.set}</strong>
        </span>
      )}
      {importing.isError && (
        <span data-testid="import-rates-error" role="alert">
          {' '}
          Nothing was set:{' '}
          {importing.error instanceof HttpError && importing.error.body
            ? importing.error.body
            : 'every line needs a rate the rate form would accept.'}
        </span>
      )}
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 5.5, Component: ImportRates });
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { useClaims } from '../claims/useClaims';
import { type Person } from '../people/usePeople';
import { showDue, useRates } from '../rates/useRates';
import { useFloor, useLate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheet';
import { personPeriodCarriedCents, personPeriodDueCents, usePeriods } from './usePeriods';

/** One header per period on the sheet. */
function PeriodColumns({ sheet }: { user: string; sheet: string }) {
  const { data: periods = [] } = usePeriods(sheet);
  return (
    <>
      {periods.map((p) => (
        <th key={p.name}>{p.name}</th>
      ))}
    </>
  );
}

/**
 * A person's due-total for every period on the sheet: the due of their claims dated in it that were
 * counted at the end of its last day (by their status log),
 * or, once the period is closed, the figure fixed then (0.00 for a person added since); and beside it
 * what they carried into it: the due of their counted claims belonging to an earlier period that were
 * still OPEN or PENDING at the end of this one, or, once the period is closed, the figure fixed then.
 */
function PersonPeriods({ sheet, person }: { user: string; sheet: string; person: Person }) {
  const { data: periods = [] } = usePeriods(sheet);
  const { data: claims = [] } = useClaims(sheet);
  const { data: rates = [] } = useRates(sheet);
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const today = useSheetToday(sheet);
  return (
    <>
      {periods.map((p) => (
        <td key={p.name}>
          <span data-testid={`person-period-${p.name}-due-total`}>
            {showDue(personPeriodDueCents(p, person, claims, rates, floor, late, today))}
          </span>{' '}
          (carried{' '}
          <span data-testid={`person-period-${p.name}-carried`}>
            {showDue(personPeriodCarriedCents(p, periods, person, claims, rates, floor, late, today))}
          </span>
          )
        </td>
      ))}
    </>
  );
}

export const contributions = [
  PersonColumns.fill({ order: 15, Component: PeriodColumns }),
  PersonCells.fill({ order: 15, Component: PersonPeriods }),
];
