package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Splits the paste into lines of name,amount,date,note (the note may hold commas, the date may be
 *  blank, the note absent) and checks each by the claim form's rules; blank lines are skipped. A
 *  note ending in ` #<reference>` gives the claim that reference (not part of the note); a reference
 *  repeated within the paste, without regard to case, refuses it. */
public class ValidatePasteClaims {
    /** A note ending in a space, a hash and the reference. */
    private static final Pattern REF = Pattern.compile("(.*) #(.+)");

    public void validate(@RequestBody PasteClaimsRequest request, Out<PastedClaims> body, Out<Actor> actor)
            throws InvalidSheetRequestException {
        String user = request == null ? null : request.user();
        String text = request == null || request.text() == null ? "" : request.text();
        List<PastedLine> lines = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        int n = 0;
        for (String raw : text.split("\\r?\\n")) {
            n++;
            if (raw.isBlank()) continue;
            String[] f = raw.split(",", 4);
            if (f.length < 2 || f[0].isBlank()) {
                throw new InvalidSheetRequestException("Line " + n + ": a name and an amount are needed");
            }
            String note = f.length > 3 ? f[3] : "";
            String ref = null;
            Matcher tagged = REF.matcher(note.trim());
            if (tagged.matches() && !tagged.group(2).isBlank()) {
                note = tagged.group(1);
                ref = tagged.group(2);
            }
            ClaimValues values;
            try {
                values = ClaimRequest.checked(new ClaimRequest(f[1], f.length > 2 ? f[2] : "", note, null, user, ref, null));
            } catch (InvalidSheetRequestException e) {
                throw new InvalidSheetRequestException("Line " + n + ": " + e.getMessage());
            }
            if (values.ref() != null && !refs.add(values.ref().toLowerCase(Locale.ROOT))) {
                throw new InvalidSheetRequestException("Line " + n + ": the reference is repeated in the paste: " + values.ref());
            }
            lines.add(new PastedLine(f[0].trim(), values));
        }
        if (lines.isEmpty()) throw new InvalidSheetRequestException("Paste at least one line of name,amount,date,note");
        actor.set(new Actor(user));
        body.set(new PastedClaims(lines, user));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The periods of each sheet. */
@Repository
public class Periods {

    private static final String COLUMNS = "SELECT sheet_id, name, from_date, to_date, closed, closed_total, soft, cap FROM period";

    private final JdbcTemplate jdbc;

    public Periods(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every period on the sheet, by from-date. */
    public List<Period> onSheet(String sheetId) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? ORDER BY from_date", Periods::period, sheetId);
    }

    /** The period of this name on this sheet, or null when there is none. Locks its row for the
     *  rest of the transaction. */
    public Period find(String sheetId, String name) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND name = ? FOR UPDATE", Periods::period, sheetId, name)
                .stream().findFirst().orElse(null);
    }

    /** The (not soft-) closed period of the sheet whose dates contain the date, or null when there is none. */
    public Period closedOn(String sheetId, LocalDate date) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND closed AND NOT soft AND from_date <= ? AND to_date >= ?",
                Periods::period, sheetId, Date.valueOf(date), Date.valueOf(date)).stream().findFirst().orElse(null);
    }

    /** The soft-closed period of the sheet whose dates contain the date, or null when there is none. */
    public Period softClosedOn(String sheetId, LocalDate date) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND closed AND soft AND from_date <= ? AND to_date >= ?",
                Periods::period, sheetId, Date.valueOf(date), Date.valueOf(date)).stream().findFirst().orElse(null);
    }

    /** The capped period of the sheet whose dates contain the date, or null when there is none. */
    public Period cappedOn(String sheetId, LocalDate date) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND cap IS NOT NULL AND from_date <= ? AND to_date >= ?",
                Periods::period, sheetId, Date.valueOf(date), Date.valueOf(date)).stream().findFirst().orElse(null);
    }

    /** How many of the person's claims due by in the period are OPEN or PENDING. */
    public int openIn(Period period, long personId) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND person_id = ?"
                + " AND status IN ('OPEN', 'PENDING') AND due_by >= ? AND due_by <= ?", Integer.class,
                period.sheetId(), personId, Date.valueOf(period.from()), Date.valueOf(period.to()));
        return n == null ? 0 : n;
    }

    public void add(Period period) {
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date, cap) VALUES (?, ?, ?, ?, ?)",
                period.sheetId(), period.name(), Date.valueOf(period.from()), Date.valueOf(period.to()), period.cap());
    }

    /** Close (or, when `soft`, soft-close) the period, fixing its due-total and each person's (by
     *  person id) afresh, and each person's carried figure for it. */
    public void close(Period period, BigDecimal total, Map<Long, BigDecimal> personTotals,
            Map<Long, BigDecimal> personCarried, boolean soft) {
        jdbc.update("UPDATE period SET closed = TRUE, soft = ?, closed_total = ? WHERE sheet_id = ? AND name = ?",
                soft, total, period.sheetId(), period.name());
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?",
                period.sheetId(), period.name());
        personTotals.forEach((personId, personTotal) -> jdbc.update(
                "INSERT INTO period_person_total (sheet_id, period_name, person_id, total, carried) VALUES (?, ?, ?, ?, ?)",
                period.sheetId(), period.name(), personId, personTotal,
                personCarried.getOrDefault(personId, BigDecimal.ZERO.setScale(2))));
    }

    /** Each person's due-total fixed when the period was closed, by person id; empty while it is open. */
    public Map<Long, BigDecimal> personTotals(Period period) {
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        jdbc.query("SELECT person_id, total FROM period_person_total WHERE sheet_id = ? AND period_name = ?"
                + " ORDER BY person_id", rs -> {
                    totals.put(rs.getLong("person_id"), rs.getBigDecimal("total"));
                }, period.sheetId(), period.name());
        return totals;
    }

    /** Each person's carried figure fixed when the period was closed, by person id; empty while it is open. */
    public Map<Long, BigDecimal> personCarried(Period period) {
        Map<Long, BigDecimal> carried = new LinkedHashMap<>();
        jdbc.query("SELECT person_id, carried FROM period_person_total WHERE sheet_id = ? AND period_name = ?"
                + " ORDER BY person_id", rs -> {
                    carried.put(rs.getLong("person_id"), rs.getBigDecimal("carried"));
                }, period.sheetId(), period.name());
        return carried;
    }

    /** Reopen the period: its due-total, and each person's due-total and carried figure, is live again. */
    public void reopen(Period period) {
        jdbc.update("UPDATE period SET closed = FALSE, soft = FALSE, closed_total = NULL WHERE sheet_id = ? AND name = ?",
                period.sheetId(), period.name());
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?",
                period.sheetId(), period.name());
    }

    private static Period period(ResultSet rs, int i) throws SQLException {
        return new Period(rs.getString("sheet_id"), rs.getString("name"), rs.getDate("from_date").toLocalDate(),
                rs.getDate("to_date").toLocalDate(), rs.getBoolean("closed"), rs.getBigDecimal("closed_total"),
                rs.getBoolean("soft"), rs.getObject("cap", Integer.class));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimLog;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Figures;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import org.springframework.stereotype.Service;

/** Closes a period, fixing its due-total as the screen shows it now: the figures (as shown now) of
 *  everyone's claims due by in it (by the due-by fixed when each was added) that were counted (OPEN, PENDING or SETTLED) by the status each had
 *  at the end of the period's last day, as its status log records it — not deferred ones, nor
 *  ones open then and dated within their person's hold, unless stated — n/a ones skipped. Each
 *  person's due-total for it is fixed too, and the period's is their sum; and so is each person's
 *  carried figure for it: the figures of their counted claims belonging, by due-by, to a period ending
 *  before this one starts that were still OPEN or PENDING at the end of its last day. Used by a close by hand
 *  and by the auto close of a today change. */
@Service
public class PeriodCloser {

    private final Periods periods;
    private final Claims claims;
    private final People people;
    private final Figures figures;
    private final ClaimLog log;

    public PeriodCloser(Periods periods, Claims claims, People people, Figures figures, ClaimLog log) {
        this.periods = periods;
        this.claims = claims;
        this.people = people;
        this.figures = figures;
        this.log = log;
    }

    /** Close the open or soft-closed period; the period as it is once closed. */
    public Period close(Period period) {
        return close(period, false);
    }

    /** Close the period, or soft-close it when `soft`; the period as it is then. */
    public Period close(Period period, boolean soft) {
        Map<Long, Person> personOf = people.onSheet(period.sheetId()).stream()
                .collect(Collectors.toMap(Person::getId, p -> p));
        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
        for (Long id : personOf.keySet()) personTotals.put(id, BigDecimal.ZERO.setScale(2));
        Map<Long, ClaimStatus> atEnd = log.statusesAt(period.sheetId(), period.to());
        for (Claim claim : claims.onSheet(period.sheetId())) {
            if (!period.contains(claim.getDueBy())) continue;
            Person person = personOf.get(claim.getPersonId());
            if (person == null || !person.counts(claim,
                    atEnd.containsKey(claim.getId()) ? atEnd.get(claim.getId()) : claim.getStatus())) continue;
            BigDecimal figure = figures.due(claim, person.gradeOn(claim.getDate()));
            if (figure != null) personTotals.merge(person.getId(), figure, BigDecimal::add);
        }
        Map<Long, BigDecimal> personCarried = carried(period, personOf, atEnd);
        BigDecimal total = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        periods.close(period, total, personTotals, personCarried, soft);
        return new Period(period.sheetId(), period.name(), period.from(), period.to(), true, total, soft, period.cap());
    }

    /** Each person's carried figure for the period as the screen shows it now, by person id. */
    private Map<Long, BigDecimal> carried(Period period, Map<Long, Person> personOf, Map<Long, ClaimStatus> atEnd) {
        Map<Long, BigDecimal> personCarried = new LinkedHashMap<>();
        for (Long id : personOf.keySet()) personCarried.put(id, BigDecimal.ZERO.setScale(2));
        List<Period> all = periods.onSheet(period.sheetId());
        for (Claim claim : claims.onSheet(period.sheetId())) {
            Period home = all.stream().filter(p -> p.contains(claim.getDueBy())).findFirst().orElse(null);
            if (home == null || !home.to().isBefore(period.from())) continue;
            Person person = personOf.get(claim.getPersonId());
            ClaimStatus status = atEnd.containsKey(claim.getId()) ? atEnd.get(claim.getId()) : claim.getStatus();
            if (person == null || status == null || !status.isOpen() || !person.counts(claim, status)) continue;
            BigDecimal figure = figures.due(claim, person.gradeOn(claim.getDate()));
            if (figure != null) personCarried.merge(person.getId(), figure, BigDecimal::add);
        }
        return personCarried;
    }
}
